import {routeBetween} from '../../world-navigation.mjs';
export function createHalloweenRuntime(plan,event,saved){
 const initial=()=>({version:1,seed:plan.seed,seconds:0,pens:[],weather:'clear',phase:'trick-or-treat',choice:false,position:{...plan.nodes[plan.home]},route:[],destination:null,visited:[],candy:0,batteries:2,light:100,resolve:3,signal:1,supplyTaken:false,log:['Three fictional friends start a Halloween walk.'],encounters:0,escaped:false});
 let s=saved?.version===1&&saved.seed===plan.seed?structuredClone(saved):initial();
 const log=t=>{s.log.push(t);s.log=s.log.slice(-10);};
 function go(id){const p=plan.nodes[id];if(!p)return false;const r=routeBetween(event.graph,s.position,p);if(!r){log('No connected walking route.');return false;}s.route=r.points.slice(1);s.destination=id;s.choice=false;return true;}
 function rise(){if(s.phase!=='trick-or-treat')return;const r=event.raise(.25);if(!r.raised){log(r.reason);return;}s.phase='rising';s.choice=false;s.route=[];event.setDestination(plan.nodes.road210);log(`${r.raised} fictional occupants rise, three hexes away. Choose the next move.`);}
 function choose(action,id){if(s.escaped)return false;if(['trick-or-treat','rising'].includes(s.phase)&&!['continue','battery'].includes(action))return false;if(!s.resolve&&!['retreat','battery','continue'].includes(action))return false;if(action==='move')return go(id);if(action==='retreat'){s.phase='retreat';return go(plan.refuge);}if(action==='supplies')return go(plan.supply);if(action==='advance')return go('road70');if(action==='battery'&&s.batteries>0&&s.light<100){s.batteries--;s.light=100;log('Fresh battery fitted.');return true;}if(action==='confront'&&s.signal>0&&s.phase!=='trick-or-treat'){s.signal--;s.resolve=Math.max(0,s.resolve-1);s.encounters++;event.setDestination(plan.nodes.road35);s.choice=false;log('A signal draws the horde toward the cemetery road. Resolve −1.');return true;}if(action==='continue'){s.choice=false;return true;}return false;}
 function update(dt){if(s.choice||s.escaped)return;dt=Math.max(0,Math.min(.25,dt));s.seconds+=dt;event.update(s.phase==='rising'?dt/6:dt);if(s.phase==='rising'){if(event.state.elapsed>=1.5){s.phase='outbreak';s.choice=true;log('The dead have emerged. Choose the next move.');}return;}if(s.phase!=='trick-or-treat')s.light=Math.max(0,s.light-dt*.15);
  if(!s.route.length&&s.phase==='trick-or-treat'){const next=plan.homes.slice(0,6).find(h=>!s.visited.includes(h.id));if(next)go(next.id);else rise();}
  let remaining=dt*3.6;while(s.route.length&&remaining>0){const p=s.route[0],d=Math.hypot(p.x-s.position.x,p.z-s.position.z);if(d<=remaining){s.position={...p};s.route.shift();remaining-=d;}else{s.position.x+=(p.x-s.position.x)*remaining/d;s.position.z+=(p.z-s.position.z)*remaining/d;remaining=0;}}
  if(!s.route.length&&s.destination){const id=s.destination;s.destination=null;if(s.phase==='trick-or-treat'&&!s.visited.includes(id)){s.visited.push(id);s.candy+=3;log(`Porch ${s.visited.length}: collected 3 treats.`);if(s.visited.length===3)rise();}else if(id===plan.supply&&!s.supplyTaken){s.batteries+=2;s.signal++;s.supplyTaken=true;s.choice=true;log('Supply cache: two batteries and one signal.');}else if(id===plan.refuge&&s.phase==='retreat'){s.escaped=true;s.choice=true;log('Everyone reached the lit porch. Night complete.');}else{s.choice=true;log('Arrived. Choose where to go next.');}}
  const near=proximity();if(s.phase!=='trick-or-treat'&&near<(s.light>0?8:12)&&s.resolve>0&&s.seconds-(s.lastEncounter??-100)>12){s.lastEncounter=s.seconds;s.resolve=Math.max(0,s.resolve-1);s.encounters++;s.choice=true;log('The horde is close. Resolve −1; choose a route or use a signal.');if(!s.resolve){s.phase='retreat';go(plan.refuge);log('The group must retreat; no more risky advances.');}}
 }
 function proximity(){return Math.min(Infinity,...Object.values(event.world.actors).filter(a=>a.alive!==false).map(a=>Math.hypot(a.position.x-s.position.x,a.position.z-s.position.z)));}
 return {get state(){return s;},update,go,choose,rise,proximity,snapshot:()=>({...structuredClone(s),cemetery:event.snapshot()}),restore(v){if(v?.seed===plan.seed)s=structuredClone(v);}};
}
